import pandas as pd

def inspect_file(filename):
    print(f"--- Inspecting {filename} ---")
    try:
        if filename.endswith('.xls'):
            df = pd.read_excel(filename, engine='xlrd', header=None, nrows=20)
        else:
            df = pd.read_excel(filename, engine='openpyxl', header=None, nrows=20)
        print(df.to_string())
    except Exception as e:
        print(f"Error reading {filename}: {e}")
    print("\n")

