def process_erp_data(filename, col_idx=1):
    # Read the file
    if filename.endswith('.xls'):
        df = pd.read_excel(filename, engine='xlrd', header=None)
    else:
        df = pd.read_excel(filename, engine='openpyxl', header=None)

    data = {}
    quarters_2024 = []
    current_year_context = None # Track year for quarterly blocks

    for index, row in df.iterrows():
        year_val = row[0]
        val = row[col_idx]

        if pd.isna(year_val) or pd.isna(val):
            continue

        year_str = str(year_val).strip()

        # Case 1: Annual Data "1973."
        if year_str.replace('.','').isdigit():
            year = int(year_str.replace('.',''))
            if 1973 <= year <= 2023:
                data[year] = float(val)
            current_year_context = None # Reset context on annual rows

        # Case 2: Quarterly Data Start "2024: I."
        elif ':' in year_str:
            parts = year_str.split(':')
            if len(parts) > 0 and parts[0].isdigit():
                year = int(parts[0])
                current_year_context = year
                if year == 2024:
                    quarters_2024.append(float(val))

        # Case 3: Subsequent Quarters "II.", "III p."
        elif current_year_context == 2024:
            # Check if it looks like a roman numeral
            # Common patterns: "II.", "III.", "III p."
            clean_str = year_str.replace('.', '').replace(' p', '').strip()
            if clean_str in ['II', 'III', 'IV']:
                quarters_2024.append(float(val))

    # Calculate 2024 average
    if quarters_2024:
        data[2024] = np.mean(quarters_2024)
        print(f"DEBUG: Found {len(quarters_2024)} quarters for 2024 in {filename}")
    else:
        print(f"DEBUG: Found NO quarters for 2024 in {filename}")

    return pd.Series(data).sort_index()
